const ws = figma.root.children.find(n=>n.id==='5:2'); await figma.setCurrentPageAsync(ws);
const P={}; for(const s of await figma.getLocalPaintStylesAsync()) P[s.name.replace('SW/','')]=s;
const log=[];
// 1. stray area outlines
const comps=[ws.findOne(n=>n.type==='COMPONENT'&&n.name==='Price Chart · NFLX 1M'), ...ws.findOne(n=>n.type==='COMPONENT_SET'&&n.name==='Portfolio Card').children];
for(const c of comps){ for(const a of c.findAll(n=>n.type==='VECTOR'&&n.name==='Area')){ a.strokes=[]; log.push('area stroke cleared in '+c.name);} }
// 2. hidden slash
const hid=ws.findOne(n=>n.type==='COMPONENT'&&n.name==='Visibility=Hidden'); const sl=hid.findOne(n=>n.name==='Hidden slash'); sl.x=7; sl.y=9.7;
// 3. remove non-brief copy
const pf=ws.findOne(n=>n.type==='COMPONENT'&&n.name==='Phone Field'); pf.findOne(n=>n.name==='Country').remove(); pf.findOne(n=>n.name==='Divider').remove(); pf.itemSpacing=4;
const f05=ws.children.find(n=>n.name==='05_Verify_Code'); const rs=f05.findOne(n=>n.name==='Resend'); rs.findOne(n=>n.type==='TEXT'&&n.characters==='Didn’t get it?').remove(); rs.x=(375-rs.width)/2;
// 4. scrolling
const names=['01_Splash','02_Onboarding','03_Sign_Up_Empty','03_Sign_Up_Filled','04_Verify_Phone','05_Verify_Code','06_Welcome','07_Home','08_Portfolio','09_Stock_Detail','10_Confirm_Order','11_Profile'];
for(const nm of names){ const f=ws.children.find(n=>n.name===nm); const sb=f.findOne(n=>n.name==='Status Bar'&&n.parent===f);
  for(const k of f.children){ if(k.name==='Main Navigation'||k.name==='Home Indicator'){ k.scrollBehavior='SCROLLS'; } }
  if(f.height>812){ await sb.setFillStyleIdAsync(P['Surface/Base'].id); sb.scrollBehavior='FIXED'; f.parent.insertChild; f.appendChild(sb); }
}
// 5. Audit
const audit={};
for(const nm of names){ const f=ws.children.find(n=>n.name===nm); const r=[]; if(f.reactions.length) r.push('frame:'+f.reactions.length);
  for(const n of f.findAll(x=>'reactions' in x && x.reactions.length)){ r.push(n.name+'→'+(await figma.getNodeByIdAsync(n.reactions[0].actions[0].destinationId)).name); }
  audit[nm]={size:f.width+'x'+f.height,links:r}; }
const texts=ws.findAll(n=>n.type==='TEXT'&&names.includes((()=>{let p=n;while(p.parent&&p.parent.type!=='PAGE')p=p.parent;return p.name;})()));
const fonts=[...new Set(texts.map(t=>t.fontName===figma.mixed?'mixed':t.fontName.family))];
const top=ws.children.map(n=>n.name);
return {log,audit,fonts,top,flows:ws.flowStartingPoints};

const ws = figma.root.children.find(n=>n.id==='5:2'); await figma.setCurrentPageAsync(ws);
for (const s of ['Regular','Medium','Semi Bold','Bold']) await figma.loadFontAsync({family:'Inter',style:s});
const P={}; for(const s of await figma.getLocalPaintStylesAsync()) P[s.name.replace('SW/','')]=s;
const log=[];
const comps=[ws.findOne(n=>n.type==='COMPONENT'&&n.name==='Price Chart · NFLX 1M'), ...ws.findOne(n=>n.type==='COMPONENT_SET'&&n.name==='Portfolio Card').children];
for(const c of comps){ for(const a of c.findAll(n=>n.type==='VECTOR'&&n.name==='Area')){ a.strokes=[]; log.push('area stroke cleared: '+c.name);} }
const hid=ws.findOne(n=>n.type==='COMPONENT'&&n.name==='Visibility=Hidden'); const sl=hid.findOne(n=>n.name==='Hidden slash'); sl.x=7; sl.y=9.7;
const pf=ws.findOne(n=>n.type==='COMPONENT'&&n.name==='Phone Field'); const cy=pf.findOne(n=>n.name==='Country'); if(cy) cy.remove(); const dv=pf.findOne(n=>n.name==='Divider'); if(dv) dv.remove(); pf.itemSpacing=4;
const f05=ws.children.find(n=>n.name==='05_Verify_Code'); const rs=f05.findOne(n=>n.name==='Resend'); const dg=rs.findOne(n=>n.type==='TEXT'&&n.characters==='Didn’t get it?'); if(dg) dg.remove(); rs.x=(375-rs.width)/2;
// Title-only header variant replaces the one-off header on 11_Profile
const hSet=ws.findOne(n=>n.type==='COMPONENT_SET'&&n.name==='Header');
let ho=hSet.children.find(c=>c.name==='Type=Title Only');
if(!ho){ ho=hSet.children.find(c=>c.name==='Type=Back').clone(); hSet.appendChild(ho); ho.name='Type=Title Only'; ho.findOne(n=>n.name==='Back').remove(); ho.findOne(n=>n.name==='Spacer').remove(); ho.primaryAxisAlignItems='CENTER'; }
const f11=ws.children.find(n=>n.name==='11_Profile'); const old=f11.findOne(n=>n.name==='Header'&&n.parent===f11);
if(old.type==='FRAME'){ const inst=ho.createInstance(); f11.insertChild(f11.children.indexOf(old),inst); inst.x=0; inst.y=44; inst.name='Header'; const k=Object.keys(inst.componentProperties).find(p=>p.startsWith('Title')); inst.setProperties({[k]:'Profile'}); old.remove(); log.push('11 header → component'); }
// Fixed-on-scroll shell for tall frames: fixed children must be last in the layer list
const names=['01_Splash','02_Onboarding','03_Sign_Up_Empty','03_Sign_Up_Filled','04_Verify_Phone','05_Verify_Code','06_Welcome','07_Home','08_Portfolio','09_Stock_Detail','10_Confirm_Order','11_Profile'];
for(const nm of names){ const f=ws.children.find(n=>n.name===nm); if(f.height<=812) continue;
  const sb=f.children.find(n=>n.name==='Status Bar'); const bot=f.children.find(n=>n.name==='Main Navigation'||n.name==='Home Indicator');
  await sb.setFillStyleIdAsync(P['Surface/Base'].id); f.appendChild(sb); f.appendChild(bot); f.numberOfFixedChildren=2; log.push(nm+' fixed='+f.numberOfFixedChildren+' overflow='+f.overflowDirection); }
const audit={};
for(const nm of names){ const f=ws.children.find(n=>n.name===nm); const r=[]; if(f.reactions.length) r.push('frame→'+(await figma.getNodeByIdAsync(f.reactions[0].actions[0].destinationId)).name);
  for(const n of f.findAll(x=>'reactions' in x && x.reactions.length)){ r.push(n.name+'→'+(await figma.getNodeByIdAsync(n.reactions[0].actions[0].destinationId)).name); }
  audit[nm]={size:f.width+'x'+f.height,links:r}; }
const rootOf=n=>{let p=n;while(p.parent&&p.parent.type!=='PAGE')p=p.parent;return p.name;};
const fonts=[...new Set(ws.findAll(n=>n.type==='TEXT').map(t=>t.fontName===figma.mixed?'mixed':t.fontName.family))];
return {log,audit,fonts,top:ws.children.map(n=>n.name+' '+n.id),flows:ws.flowStartingPoints};

const ws = figma.root.children.find(n=>n.id==='5:2'); await figma.setCurrentPageAsync(ws);
for (const s of ['Regular','Medium','Semi Bold','Bold']) await figma.loadFontAsync({family:'Inter',style:s});
const hSet=ws.findOne(n=>n.type==='COMPONENT_SET'&&n.name==='Header');
const ho=hSet.children.find(c=>c.name==='Type=Title Only');
const defs=Object.keys(hSet.componentPropertyDefinitions);
const tt=ho.findOne(n=>n.type==='TEXT');
const before={defs,refs:tt.componentPropertyReferences,variants:hSet.children.map(c=>c.name+':'+JSON.stringify(c.findOne(n=>n.type==='TEXT').componentPropertyReferences))};
const titleKey=defs.find(k=>k.startsWith('Title'));
tt.componentPropertyReferences={characters:titleKey};
const f11=ws.children.find(n=>n.name==='11_Profile'); const inst=f11.children.find(n=>n.name==='Header');
inst.setProperties({[titleKey]:'Profile'});
const f09=ws.children.find(n=>n.name==='09_Stock_Detail'), f08=ws.children.find(n=>n.name==='08_Portfolio'), f10=ws.children.find(n=>n.name==='10_Confirm_Order');
const titles=[f08,f09,f10,f11].map(f=>f.name+': '+f.children.find(n=>n.name==='Header').findOne(n=>n.type==='TEXT').characters);
const c=ws.findOne(n=>n.type==='COMPONENT'&&n.name==='Portfolio Week Chart');
const bars=c.findAll(n=>n.name==='Bar').map(b=>b.width);
return {before,titles,inst:inst.mainComponent.name,bars};

const ws = figma.root.children.find(n=>n.id==='5:2'); await figma.setCurrentPageAsync(ws);
const home=ws.children.find(n=>n.name==='07_Home');
const row=home.findOne(n=>n.name==='Index cards');
const sp=row.children.find(n=>n.name==='Index · S&P 500'), dj=row.children.find(n=>n.name==='Index · Dow Jones');
const h=Math.max(sp.height,dj.height);
row.counterAxisSizingMode='FIXED'; row.resize(row.width,h);
sp.layoutSizingVertical='FILL'; dj.layoutSizingVertical='FILL';
dj.primaryAxisAlignItems='SPACE_BETWEEN';
const ct=home.findOne(n=>n.name==='Content');
return {h,sp:sp.height,dj:dj.height,contentBottom:ct.y+ct.height,frame:home.height,nav:home.children.find(n=>n.name==='Main Navigation').y};
